import 'dart:ui';\nimport '../design_system.dart';\n\n/// Bezel-mounted tab system for Morph-UI\n/// Tabs are positioned on screen edges and never cover the visualizer\nclass BezelTabSystem extends StatefulWidget {\n  final List<BezelTab> leftTabs;\n  final List<BezelTab> rightTabs;\n  final List<BezelTab> topTabs;\n  final List<BezelTab> bottomTabs;\n  final String activeTabId;\n  final ValueChanged<String>? onTabChanged;\n  final bool enableReordering;\n  final EdgeInsets safeAreaPadding;\n  \n  const BezelTabSystem({\n    Key? key,\n    this.leftTabs = const [],\n    this.rightTabs = const [],\n    this.topTabs = const [],\n    this.bottomTabs = const [],\n    this.activeTabId = '',\n    this.onTabChanged,\n    this.enableReordering = true,\n    this.safeAreaPadding = EdgeInsets.zero,\n  }) : super(key: key);\n  \n  @override\n  State<BezelTabSystem> createState() => _BezelTabSystemState();\n}\n\nclass _BezelTabSystemState extends State<BezelTabSystem>\n    with TickerProviderStateMixin {\n  String? _draggedTabId;\n  BezelPosition? _dragTargetPosition;\n  \n  @override\n  Widget build(BuildContext context) {\n    return Stack(\n      children: [\n        // Left tabs\n        if (widget.leftTabs.isNotEmpty)\n          _buildTabColumn(\n            widget.leftTabs,\n            BezelPosition.left,\n            Alignment.centerLeft,\n          ),\n        \n        // Right tabs\n        if (widget.rightTabs.isNotEmpty)\n          _buildTabColumn(\n            widget.rightTabs,\n            BezelPosition.right,\n            Alignment.centerRight,\n          ),\n        \n        // Top tabs\n        if (widget.topTabs.isNotEmpty)\n          _buildTabRow(\n            widget.topTabs,\n            BezelPosition.top,\n            Alignment.topCenter,\n          ),\n        \n        // Bottom tabs\n        if (widget.bottomTabs.isNotEmpty)\n          _buildTabRow(\n            widget.bottomTabs,\n            BezelPosition.bottom,\n            Alignment.bottomCenter,\n          ),\n      ],\n    );\n  }\n  \n  Widget _buildTabColumn(\n    List<BezelTab> tabs,\n    BezelPosition position,\n    Alignment alignment,\n  ) {\n    return Positioned.fill(\n      child: Align(\n        alignment: alignment,\n        child: Container(\n          margin: EdgeInsets.only(\n            left: position == BezelPosition.left ? widget.safeAreaPadding.left : 0,\n            right: position == BezelPosition.right ? widget.safeAreaPadding.right : 0,\n            top: widget.safeAreaPadding.top + 60,\n            bottom: widget.safeAreaPadding.bottom + 60,\n          ),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: tabs.map((tab) => _buildBezelTabWidget(\n              tab,\n              position,\n            )).toList(),\n          ),\n        ),\n      ),\n    );\n  }\n  \n  Widget _buildTabRow(\n    List<BezelTab> tabs,\n    BezelPosition position,\n    Alignment alignment,\n  ) {\n    return Positioned.fill(\n      child: Align(\n        alignment: alignment,\n        child: Container(\n          margin: EdgeInsets.only(\n            left: widget.safeAreaPadding.left + 60,\n            right: widget.safeAreaPadding.right + 60,\n            top: position == BezelPosition.top ? widget.safeAreaPadding.top : 0,\n            bottom: position == BezelPosition.bottom ? widget.safeAreaPadding.bottom : 0,\n          ),\n          child: Row(\n            mainAxisSize: MainAxisSize.min,\n            children: tabs.map((tab) => _buildBezelTabWidget(\n              tab,\n              position,\n            )).toList(),\n          ),\n        ),\n      ),\n    );\n  }\n  \n  Widget _buildBezelTabWidget(\n    BezelTab tab,\n    BezelPosition position,\n  ) {\n    final isActive = tab.id == widget.activeTabId;\n    final isDragTarget = _dragTargetPosition == position;\n    \n    return Padding(\n      padding: const EdgeInsets.all(4),\n      child: widget.enableReordering\n        ? _buildDraggableTab(tab, position, isActive, isDragTarget)\n        : _buildStaticTab(tab, position, isActive),\n    );\n  }\n  \n  Widget _buildDraggableTab(\n    BezelTab tab,\n    BezelPosition position,\n    bool isActive,\n    bool isDragTarget,\n  ) {\n    return LongPressDraggable<BezelTab>(\n      data: tab,\n      onDragStarted: () {\n        setState(() => _draggedTabId = tab.id);\n      },\n      onDragEnd: (details) {\n        setState(() {\n          _draggedTabId = null;\n          _dragTargetPosition = null;\n        });\n      },\n      feedback: Material(\n        color: Colors.transparent,\n        child: _buildTabContent(tab, position, true, false),\n      ),\n      childWhenDragging: Opacity(\n        opacity: 0.3,\n        child: _buildTabContent(tab, position, isActive, isDragTarget),\n      ),\n      child: DragTarget<BezelTab>(\n        onWillAccept: (data) => data?.id != tab.id,\n        onAccept: (data) {\n          // Handle tab reordering\n          _reorderTabs(data, tab, position);\n        },\n        onMove: (details) {\n          setState(() => _dragTargetPosition = position);\n        },\n        onLeave: (data) {\n          setState(() => _dragTargetPosition = null);\n        },\n        builder: (context, candidateData, rejectedData) {\n          return _buildTabContent(tab, position, isActive, candidateData.isNotEmpty);\n        },\n      ),\n    );\n  }\n  \n  Widget _buildStaticTab(\n    BezelTab tab,\n    BezelPosition position,\n    bool isActive,\n  ) {\n    return _buildTabContent(tab, position, isActive, false);\n  }\n  \n  Widget _buildTabContent(\n    BezelTab tab,\n    BezelPosition position,\n    bool isActive,\n    bool isDragTarget,\n  ) {\n    final isVertical = position == BezelPosition.left || position == BezelPosition.right;\n    \n    return GestureDetector(\n      onTap: () => widget.onTabChanged?.call(tab.id),\n      child: AnimatedContainer(\n        duration: const Duration(milliseconds: 200),\n        width: isVertical ? 40 : (tab.label.length * 8 + 24),\n        height: isVertical ? (tab.label.length * 8 + 24) : 40,\n        decoration: BoxDecoration(\n          gradient: LinearGradient(\n            colors: [\n              tab.color.withOpacity(isActive ? 0.3 : 0.1),\n              tab.color.withOpacity(isActive ? 0.2 : 0.05),\n            ],\n          ),\n          borderRadius: BorderRadius.circular(8),\n          border: Border.all(\n            color: tab.color.withOpacity(isActive ? 0.6 : 0.3),\n            width: isDragTarget ? 2 : 1,\n          ),\n          boxShadow: [\n            if (isActive)\n              BoxShadow(\n                color: tab.color.withOpacity(0.4),\n                blurRadius: 8,\n                spreadRadius: 2,\n              ),\n          ],\n        ),\n        child: ClipRRect(\n          borderRadius: BorderRadius.circular(8),\n          child: BackdropFilter(\n            filter: ImageFilter.blur(sigmaX: 5, sigmaY: 5),\n            child: Center(\n              child: isVertical\n                ? RotatedBox(\n                    quarterTurns: position == BezelPosition.left ? 3 : 1,\n                    child: _buildTabText(tab, isActive),\n                  )\n                : _buildTabText(tab, isActive),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n  \n  Widget _buildTabText(BezelTab tab, bool isActive) {\n    return Text(\n      tab.label,\n      style: SyntherTypography.labelSmall.copyWith(\n        color: isActive ? tab.color : tab.color.withOpacity(0.8),\n        fontSize: 10,\n        fontWeight: isActive ? FontWeight.w600 : FontWeight.w400,\n      ),\n      textAlign: TextAlign.center,\n    );\n  }\n  \n  void _reorderTabs(BezelTab draggedTab, BezelTab targetTab, BezelPosition position) {\n    // Implementation for tab reordering\n    // This would typically call a callback to update the parent widget's tab list\n  }\n}\n\n/// Individual bezel tab data\nclass BezelTab {\n  final String id;\n  final String label;\n  final Color color;\n  final VoidCallback? onTap;\n  final Widget? icon;\n  final String? tooltip;\n  \n  const BezelTab({\n    required this.id,\n    required this.label,\n    this.color = DesignTokens.neonCyan,\n    this.onTap,\n    this.icon,\n    this.tooltip,\n  });\n}\n\n/// Bezel position enumeration\nenum BezelPosition {\n  left,\n  right,\n  top,\n  bottom,\n}\n\n/// Animated bezel tab that expands on activation\nclass AnimatedBezelTab extends StatefulWidget {\n  final BezelTab tab;\n  final BezelPosition position;\n  final bool isActive;\n  final VoidCallback? onTap;\n  \n  const AnimatedBezelTab({\n    Key? key,\n    required this.tab,\n    required this.position,\n    this.isActive = false,\n    this.onTap,\n  }) : super(key: key);\n  \n  @override\n  State<AnimatedBezelTab> createState() => _AnimatedBezelTabState();\n}\n\nclass _AnimatedBezelTabState extends State<AnimatedBezelTab>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n  late Animation<double> _expansionAnimation;\n  late Animation<double> _glowAnimation;\n  \n  @override\n  void initState() {\n    super.initState();\n    \n    _controller = AnimationController(\n      duration: const Duration(milliseconds: 300),\n      vsync: this,\n    );\n    \n    _expansionAnimation = Tween<double>(\n      begin: 1.0,\n      end: 1.2,\n    ).animate(CurvedAnimation(\n      parent: _controller,\n      curve: Curves.elasticOut,\n    ));\n    \n    _glowAnimation = Tween<double>(\n      begin: 0.0,\n      end: 1.0,\n    ).animate(CurvedAnimation(\n      parent: _controller,\n      curve: Curves.easeInOut,\n    ));\n    \n    if (widget.isActive) {\n      _controller.forward();\n    }\n  }\n  \n  @override\n  void didUpdateWidget(AnimatedBezelTab oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    if (widget.isActive != oldWidget.isActive) {\n      if (widget.isActive) {\n        _controller.forward();\n      } else {\n        _controller.reverse();\n      }\n    }\n  }\n  \n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n  \n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        return Transform.scale(\n          scale: _expansionAnimation.value,\n          child: Container(\n            decoration: BoxDecoration(\n              boxShadow: [\n                BoxShadow(\n                  color: widget.tab.color.withOpacity(0.4 * _glowAnimation.value),\n                  blurRadius: 20 * _glowAnimation.value,\n                  spreadRadius: 5 * _glowAnimation.value,\n                ),\n              ],\n            ),\n            child: GestureDetector(\n              onTap: widget.onTap,\n              child: Container(\n                padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n                decoration: BoxDecoration(\n                  gradient: LinearGradient(\n                    colors: [\n                      widget.tab.color.withOpacity(0.3),\n                      widget.tab.color.withOpacity(0.1),\n                    ],\n                  ),\n                  borderRadius: BorderRadius.circular(8),\n                  border: Border.all(\n                    color: widget.tab.color,\n                    width: 1,\n                  ),\n                ),\n                child: Text(\n                  widget.tab.label,\n                  style: SyntherTypography.labelSmall.copyWith(\n                    color: widget.tab.color,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        );\n      },\n    );\n  }\n}\n\n/// Bezel tab presets for common layouts\nclass BezelTabPresets {\n  static List<BezelTab> layoutTabs = [\n    BezelTab(\n      id: 'layout_a',\n      label: 'A',\n      color: DesignTokens.neonCyan,\n    ),\n    BezelTab(\n      id: 'layout_b',\n      label: 'B',\n      color: DesignTokens.neonPurple,\n    ),\n    BezelTab(\n      id: 'layout_c',\n      label: 'C',\n      color: DesignTokens.neonPink,\n    ),\n  ];\n  \n  static List<BezelTab> functionTabs = [\n    BezelTab(\n      id: 'xy_pad',\n      label: 'XY PAD',\n      color: DesignTokens.neonCyan,\n    ),\n    BezelTab(\n      id: 'controls',\n      label: 'CONTROLS',\n      color: DesignTokens.neonPurple,\n    ),\n    BezelTab(\n      id: 'keyboard',\n      label: 'KEYBOARD',\n      color: DesignTokens.neonPink,\n    ),\n  ];\n  \n  static List<BezelTab> modeTabs = [\n    BezelTab(\n      id: 'drum_pads',\n      label: 'DRUMS',\n      color: DesignTokens.neonPink,\n    ),\n    BezelTab(\n      id: 'piano',\n      label: 'PIANO',\n      color: DesignTokens.neonCyan,\n    ),\n    BezelTab(\n      id: 'presets',\n      label: 'PRESETS',\n      color: DesignTokens.neonPurple,\n    ),\n    BezelTab(\n      id: 'settings',\n      label: 'SETTINGS',\n      color: DesignTokens.textSecondary,\n    ),\n  ];\n}"